//! Controlled single-host synchronous failover of an in-flight grant change.
use jsonwebtoken::{Algorithm,EncodingKey,Header,encode};
use serde_json::{Value,json};
use std::{process::{Child,Command,Stdio},time::{Duration,SystemTime,UNIX_EPOCH}};
use tokio_postgres::{Client,NoTls};

async fn connect(url:&str)->Client {for _ in 0..100{if let Ok((db,driver))=tokio_postgres::connect(url,NoTls).await{tokio::spawn(driver);return db;}tokio::time::sleep(Duration::from_millis(100)).await;}panic!("database unavailable")}
struct Server(Child);
impl Drop for Server {fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}
fn port()->u16 {let socket=std::net::TcpListener::bind("127.0.0.1:0").unwrap();socket.local_addr().unwrap().port()}
fn server(port:u16,url:&str,config:&str)->Server {Server(Command::new(env!("CARGO_BIN_EXE_novu-rust-api")).env_clear().env("DATABASE_URL",url).env("NOVU_POSTGRES_ALLOW_INSECURE","true").env("LISTEN_ADDR",format!("127.0.0.1:{port}")).env("SWALLOW_OPERATOR_JWT_CONFIG",config).env("SWALLOW_API_HEALTH_ENDPOINTS_ENABLED","true").env("SWALLOW_API_DB_HEALTH_INTERVAL_SECONDS","1").env("SWALLOW_API_DB_HEALTH_TIMEOUT_SECONDS","2").stdout(Stdio::null()).stderr(Stdio::null()).spawn().unwrap())}
async fn ready(c:&reqwest::Client,port:u16){for _ in 0..200{if c.get(format!("http://127.0.0.1:{port}/health/ready")).send().await.is_ok_and(|r|r.status().as_u16()==200){return;}tokio::time::sleep(Duration::from_millis(100)).await;}panic!("API did not become ready")}
async fn change(c:&reqwest::Client,port:u16,token:&str,body:&Value)->reqwest::Result<reqwest::Response>{c.put(format!("http://127.0.0.1:{port}/v1/experimental/operator/execution-grants?environmentId=ha-execution-env")).bearer_auth(token).json(body).send().await}
async fn trigger(c:&reqwest::Client,port:u16,token:&str)->reqwest::Result<reqwest::Response>{c.post(format!("http://127.0.0.1:{port}/v1/experimental/operator/events/trigger?environmentId=ha-execution-env")).bearer_auth(token).json(&json!({"name":"welcome","to":"alice","payload":{},"transactionId":"denied-after"})).send().await}
fn token(subject:&str)->String {let now=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();let mut h=Header::new(Algorithm::RS256);h.typ=Some("at+jwt".into());h.kid=Some("fixture".into());encode(&h,&json!({"iss":"https://issuer.test","sub":subject,"aud":"swallow","exp":now+600,"iat":now-1,"jti":subject,"client_id":"console"}),&EncodingKey::from_rsa_pem(include_bytes!("fixtures/operator_jwt/test-only-private.pem")).unwrap()).unwrap()}

#[tokio::test]
#[ignore="requires disposable synchronous PostgreSQL pair; stops primary"]
async fn execution_grant_change_survives_synchronous_promotion() {
 let primary_url=std::env::var("TEST_PRIMARY_URL").unwrap();let standby_url=std::env::var("TEST_STANDBY_URL").unwrap();let cluster_url=std::env::var("TEST_FAILOVER_URL").unwrap().replacen("postgres://postgres@","postgres://execution_ha_api@",1);let primary=std::env::var("TEST_LOCAL_PRIMARY_DATA").unwrap();let standby=std::env::var("TEST_LOCAL_STANDBY_DATA").unwrap();let pgctl=std::env::var("TEST_LOCAL_PG_CTL").unwrap();
 let mut db=connect(&primary_url).await;let observer=connect(&primary_url).await;let replica=connect(&standby_url).await;
 db.batch_execute("CREATE ROLE execution_ha_api LOGIN; GRANT USAGE ON SCHEMA public TO execution_ha_api; GRANT SELECT ON public.novu_rust_workflows,public.novu_rust_environments TO execution_ha_api; GRANT EXECUTE ON FUNCTION public.novu_rust_operator_jwt_execution_grant_change(text,text,text,text,bigint,uuid,text,text,text,text,jsonb,jsonb,text),public.novu_rust_operator_jwt_execution_grant_request(text,text,text,text,bigint,uuid),public.novu_rust_operator_jwt_trigger_authorize(text,text,text,text,bigint,text),public.novu_rust_operator_jwt_trigger_enqueue(text,text,text,text,bigint,text,text,uuid,text,jsonb,jsonb) TO execution_ha_api; INSERT INTO public.novu_rust_operator_jwt_api_logins SELECT rolname,oid FROM pg_roles WHERE rolname='execution_ha_api'; INSERT INTO public.novu_rust_environments VALUES('ha-execution-env','org'); INSERT INTO public.novu_rust_operator_jwt_identities(issuer,subject,client_id,environment_id) VALUES('https://issuer.test','admin','console','ha-execution-env'),('https://issuer.test','target','console','ha-execution-env'); INSERT INTO public.novu_rust_operator_jwt_execution_grant_admins VALUES('https://issuer.test','admin','console','ha-execution-env',true,true); INSERT INTO public.novu_rust_workflows(environment_id,identifier,active,has_steps,in_app_content,inbox_metadata) VALUES('ha-execution-env','welcome',true,true,'Hello','{\"id\":\"gen-1\"}')").await.unwrap();
 let cfg=json!({"issuer":"https://issuer.test","audience":"swallow","keys":[{"kid":"fixture","pem":std::str::from_utf8(include_bytes!("fixtures/operator_jwt/test-only-public.pem")).unwrap()}]}).to_string();let admin=token("admin");let target=token("target");let p1=port();let mut p2=port();while p1==p2{p2=port();}let mut first=server(p1,&cluster_url,&cfg);let mut second=server(p2,&cluster_url,&cfg);let client=reqwest::Client::builder().timeout(Duration::from_secs(10)).build().unwrap();ready(&client,p1).await;ready(&client,p2).await;
 let absent=json!({"granted":false,"workflowInternalId":null});let bound=json!({"granted":true,"workflowInternalId":"gen-1"});let make=|id:&str,expected:Value,desired:Value|json!({"requestId":id,"targetIssuer":"https://issuer.test","targetSubject":"target","targetClientId":"console","workflow":"welcome","expected":expected,"desired":desired,"reason":"failover fixture"});let initial=make("11111111-1111-4111-8111-111111111111",absent.clone(),bound.clone());let revoke=make("22222222-2222-4222-8222-222222222222",bound.clone(),absent.clone());
 assert_eq!(change(&client,p1,&admin,&initial).await.unwrap().status().as_u16(),200);let mut replicated=false;for _ in 0..100{replicated=replica.query_one("SELECT EXISTS(SELECT 1 FROM public.novu_rust_operator_jwt_trigger_execute_grants WHERE environment_id='ha-execution-env' AND subject='target' AND workflow_internal_id='gen-1')",&[]).await.unwrap().get(0);if replicated{break}tokio::time::sleep(Duration::from_millis(50)).await;}assert!(replicated);
 db.batch_execute("CREATE FUNCTION public.test_execution_ha_pause() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.request_id='22222222-2222-4222-8222-222222222222' THEN PERFORM pg_advisory_xact_lock(874216); END IF; RETURN NEW; END $$; CREATE TRIGGER test_execution_ha_pause BEFORE INSERT ON public.novu_rust_operator_jwt_execution_grant_changes FOR EACH ROW EXECUTE FUNCTION public.test_execution_ha_pause()").await.unwrap();
 let blocker=db.transaction().await.unwrap();blocker.query_one("SELECT pg_advisory_xact_lock(874216)",&[]).await.unwrap();let requester=client.clone();let pending_token=admin.clone();let pending_body=revoke.clone();let pending=tokio::spawn(async move{change(&requester,p1,&pending_token,&pending_body).await});
 let mut waiting=false;for _ in 0..150{waiting=observer.query_one("SELECT EXISTS(SELECT 1 FROM pg_stat_activity WHERE wait_event='advisory' AND query LIKE '%novu_rust_operator_jwt_execution_grant_change%')",&[]).await.unwrap().get(0);if waiting{break}assert!(first.0.try_wait().unwrap().is_none()&&second.0.try_wait().unwrap().is_none());tokio::time::sleep(Duration::from_millis(20)).await;}assert!(waiting);
 assert!(Command::new(&pgctl).args(["-D",&primary,"-m","immediate","stop","-w"]).stdout(Stdio::null()).status().unwrap().success());assert!(Command::new(&pgctl).args(["-D",&standby,"promote","-w"]).stdout(Stdio::null()).status().unwrap().success());assert!(!pending.await.unwrap().is_ok_and(|r|r.status().as_u16()==200));drop(blocker);ready(&client,p1).await;ready(&client,p2).await;
 let promoted=connect(&standby_url).await;let row=promoted.query_one("SELECT (SELECT count(*) FROM public.novu_rust_operator_jwt_trigger_execute_grants WHERE environment_id='ha-execution-env' AND subject='target'),(SELECT count(*) FROM public.novu_rust_operator_jwt_execution_grant_changes WHERE environment_id='ha-execution-env' AND request_id='22222222-2222-4222-8222-222222222222')",&[]).await.unwrap();assert_eq!(row.get::<_,i64>(0),1);assert_eq!(row.get::<_,i64>(1),0);
 // The test pause is no longer useful after promotion, so remove it before retry.
 promoted.batch_execute("DROP TRIGGER test_execution_ha_pause ON public.novu_rust_operator_jwt_execution_grant_changes; DROP FUNCTION public.test_execution_ha_pause()").await.unwrap();
 let (a,b)=tokio::join!(change(&client,p1,&admin,&revoke),change(&client,p2,&admin,&revoke));let a=a.unwrap();let b=b.unwrap();assert_eq!(a.status().as_u16(),200);assert_eq!(b.status().as_u16(),200);let a:Value=a.json().await.unwrap();let b:Value=b.json().await.unwrap();assert_eq!(a["changed"],true);assert_eq!(b["changed"],true);assert_ne!(a["replayed"],b["replayed"]);
 let row=promoted.query_one("SELECT (SELECT count(*) FROM public.novu_rust_operator_jwt_trigger_execute_grants WHERE environment_id='ha-execution-env' AND subject='target'),(SELECT count(*) FROM public.novu_rust_operator_jwt_execution_grant_changes WHERE environment_id='ha-execution-env' AND request_id='22222222-2222-4222-8222-222222222222')",&[]).await.unwrap();assert_eq!(row.get::<_,i64>(0),0);assert_eq!(row.get::<_,i64>(1),1);
 for port in [p1,p2]{
  assert_eq!(trigger(&client,port,&target).await.unwrap().status().as_u16(),401);
  let response=client.get(format!("http://127.0.0.1:{port}/v1/experimental/operator/execution-grants/request?environmentId=ha-execution-env&requestId=22222222-2222-4222-8222-222222222222")).bearer_auth(&admin).send().await.unwrap();assert_eq!(response.status().as_u16(),200);let result:Value=response.json().await.unwrap();assert_eq!(result["found"],true);assert_eq!(result["desired"],absent);
 }
 assert_eq!(promoted.query_one("SELECT count(*) FROM public.novu_queue_jobs WHERE environment_id='ha-execution-env' AND payload->>'transactionId'='denied-after'",&[]).await.unwrap().get::<_,i64>(0),0);
}
